name: DCO Advisor Bot

on:
  pull_request_target:
    types: [opened, reopened, synchronize]

permissions:
  pull-requests: write
  issues: write

jobs:
  dco_advisor:
    runs-on: ubuntu-latest
    steps:
      - name: Handle DCO check result
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const pr = context.payload.pull_request || context.payload.check_run?.pull_requests?.[0];
            if (!pr) return;

            const prNumber = pr.number;
            const baseRef = pr.base.ref;
            const headSha =
              context.payload.check_run?.head_sha ||
              pr.head?.sha;
            const username = pr.user.login;

            console.log("HEAD SHA:", headSha);

            const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

            // Poll until DCO check has a conclusion (max 6 attempts, 30s)
            let dcoCheck = null;
            for (let attempt = 0; attempt < 6; attempt++) {
              const { data: checks } = await github.rest.checks.listForRef({
                owner: context.repo.owner,
                repo: context.repo.repo,
                ref: headSha
              });


              console.log("All check runs:");
                checks.check_runs.forEach(run => {
                console.log(`- ${run.name} (${run.status}/${run.conclusion}) @ ${run.head_sha}`);
              });

              dcoCheck = checks.check_runs.find(run =>
                run.name.toLowerCase().includes("dco") &&
              !run.name.toLowerCase().includes("dco_advisor") &&
                run.head_sha === headSha
              );


              if (dcoCheck?.conclusion) break;
              console.log(`Waiting for DCO check... (${attempt + 1})`);
              await sleep(5000); // wait 5 seconds
            }

            if (!dcoCheck || !dcoCheck.conclusion) {
              console.log("DCO check did not complete in time.");
              return;
            }

            const isFailure = ["failure", "action_required"].includes(dcoCheck.conclusion);
            console.log(`DCO check conclusion for ${headSha}: ${dcoCheck.conclusion} (treated as ${isFailure ? "failure" : "success"})`);

            // Parse DCO output for commit SHAs and author
            let badCommits = [];
            let authorName = "";
            let authorEmail = "";
            let moreInfo = `More info: [DCO check report](${dcoCheck?.html_url})`;

            if (isFailure) {
                const { data: commits } = await github.rest.pulls.listCommits({
                    owner: context.repo.owner,
                    repo: context.repo.repo,
                    pull_number: prNumber,
                });

                for (const commit of commits) {
                    const commitMessage = commit.commit.message;
                    const signoffMatch = commitMessage.match(/^Signed-off-by:\s+.+<.+>$/m);
                    if (!signoffMatch) {
                        console.log(`Bad commit found ${commit.sha}`)
                        badCommits.push({
                        sha: commit.sha,
                        authorName: commit.commit.author.name,
                        authorEmail: commit.commit.author.email,
                        });
                    }
                }            
            }

            // If multiple authors are present, you could adapt the message accordingly
            // For now, we'll just use the first one
            if (badCommits.length > 0) {
            authorName = badCommits[0].authorName;
            authorEmail = badCommits[0].authorEmail;
            }

            // Generate remediation commit message if needed
            let remediationSnippet = "";
            if (badCommits.length && authorEmail) {
              remediationSnippet = `git commit --allow-empty -s -m "DCO Remediation Commit for ${authorName} <${authorEmail}>\n\n` +
                badCommits.map(c => `I, ${c.authorName} <${c.authorEmail}>, hereby add my Signed-off-by to this commit: ${c.sha}`).join('\n') +
                `"`;
            } else {
              remediationSnippet = "# Unable to auto-generate remediation message. Please check the DCO check details.";
            }

            // Build comment
            const commentHeader = '<!-- dco-advice-bot -->';
            let body = "";

            if (isFailure) {
              body = [
                commentHeader,
                '❌ **DCO Check Failed**',
                '',
                `Hi @${username}, your pull request has failed the Developer Certificate of Origin (DCO) check.`,
                '',
                'This repository supports **remediation commits**, so you can fix this without rewriting history — but you must follow the required message format.',
                '',
                '---',
                '',
                '### 🛠 Quick Fix: Add a remediation commit',
                'Run this command:',
                '',
                '```bash',
                remediationSnippet,
                'git push',
                '```',
                '',
                '---',
                '',
                '<details>',
                '<summary>🔧 Advanced: Sign off each commit directly</summary>',
                '',
                '**For the latest commit:**',
                '```bash',
                'git commit --amend --signoff',
                'git push --force-with-lease',
                '```',
                '',
                '**For multiple commits:**',
                '```bash',
                `git rebase --signoff origin/${baseRef}`,
                'git push --force-with-lease',
                '```',
                '',
                '</details>',
                '',
                moreInfo
              ].join('\n');
            } else {
              body = [
                commentHeader,
                '✅ **DCO Check Passed**',
                '',
                `Thanks @${username}, all your commits are properly signed off. 🎉`
              ].join('\n');
            }

            // Get existing comments on the PR
            const { data: comments } = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber
            });

            // Look for a previous bot comment
            const existingComment = comments.find(c =>
              c.body.includes("<!-- dco-advice-bot -->")
            );

            if (existingComment) {
              await github.rest.issues.updateComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                comment_id: existingComment.id,
                body: body
              });
            } else {
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: prNumber,
                body: body
              });
            }

"""Utilities to map CVAT page-level identifiers to document metadata."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import TYPE_CHECKING, Dict, Iterable, List, Optional

if TYPE_CHECKING:
    from docling_cvat_tools.datamodels.cvat_types import (
        AnnotatedImage,
        AnnotationOverview,
    )


def _canonical_page_id(doc_hash: str, page_no: int) -> str:
    return f"{doc_hash}__page_{page_no:05d}"


@dataclass(frozen=True)
class PageRef:
    """Reference metadata for a single annotated page."""

    doc_hash: str
    doc_name: str
    page_no: int
    image_name: str

    @property
    def canonical_page_id(self) -> str:
        return _canonical_page_id(self.doc_hash, self.page_no)


class CvatPageMapping:
    """Lookup helper backed by ``cvat_overview.json``."""

    def __init__(
        self,
        pages_by_doc_hash: Dict[str, List[PageRef]],
        pages_by_doc_name: Dict[str, List[PageRef]],
        pages_by_image_name: Dict[str, PageRef],
    ) -> None:
        self._pages_by_doc_hash = pages_by_doc_hash
        self._pages_by_doc_name = pages_by_doc_name
        self._pages_by_image_name = pages_by_image_name

    @classmethod
    def from_overview(cls, overview: "AnnotationOverview") -> "CvatPageMapping":
        # Import only when this method is called
        from docling_cvat_tools.datamodels.cvat_types import (
            AnnotatedImage,
            AnnotationOverview,
        )

        pages_by_doc_hash: Dict[str, List[PageRef]] = {}
        pages_by_doc_name: Dict[str, List[PageRef]] = {}
        pages_by_image_name: Dict[str, PageRef] = {}

        doc_lookup = {doc.doc_hash: doc.doc_name for doc in overview.doc_annotations}

        def build_page_refs(
            image_name: str, image: AnnotatedImage
        ) -> Iterable[PageRef]:
            if not image.page_nos:
                return []
            doc_name = doc_lookup.get(image.doc_hash, image.doc_name)
            return [
                PageRef(
                    doc_hash=image.doc_hash,
                    doc_name=doc_name,
                    page_no=page_no,
                    image_name=image_name,
                )
                for page_no in image.page_nos
            ]

        for image_name, image in overview.img_annotations.items():
            for ref in build_page_refs(image_name, image):
                pages_by_doc_hash.setdefault(ref.doc_hash, []).append(ref)
                pages_by_doc_name.setdefault(ref.doc_name, []).append(ref)
                pages_by_image_name.setdefault(ref.image_name, ref)

        def sort_refs(refs: List[PageRef]) -> None:
            refs.sort(key=lambda ref: ref.page_no)

        for refs in pages_by_doc_hash.values():
            sort_refs(refs)
        for refs in pages_by_doc_name.values():
            sort_refs(refs)

        return cls(
            pages_by_doc_hash=pages_by_doc_hash,
            pages_by_doc_name=pages_by_doc_name,
            pages_by_image_name=pages_by_image_name,
        )

    @classmethod
    def from_overview_path(cls, overview_path: Path) -> "CvatPageMapping":
        # Import only when this method is called
        from docling_cvat_tools.datamodels.cvat_types import AnnotationOverview

        overview = AnnotationOverview.load_from_json(overview_path)
        return cls.from_overview(overview)

    def pages_for_doc_hash(self, doc_hash: str) -> List[PageRef]:
        return self._pages_by_doc_hash.get(doc_hash, [])

    def pages_for_doc_name(self, doc_name: str) -> List[PageRef]:
        return self._pages_by_doc_name.get(doc_name, [])

    def page_for_image(self, image_name: str) -> Optional[PageRef]:
        return self._pages_by_image_name.get(image_name)

    def iter_pages(self) -> Iterable[PageRef]:
        for refs in self._pages_by_doc_hash.values():
            yield from refs

import json
import logging
from enum import Enum
from io import BytesIO
from pathlib import Path
from typing import Dict, List, Optional, Tuple, Union

import PIL
from datasets import Features
from datasets import Image as Features_Image
from datasets import Sequence, Value
from docling.datamodel.base_models import ConversionStatus
from docling_core.types import DoclingDocument
from docling_core.types.doc import CoordOrigin
from docling_core.types.doc.page import SegmentedPage
from docling_core.types.io import DocumentStream
from pydantic import BaseModel, ConfigDict, Field, TypeAdapter, model_validator

from docling_eval.datamodels.types import EvaluationModality, PredictionFormats
from docling_eval.utils.utils import extract_images

_log = logging.getLogger(__name__)

seg_adapter = TypeAdapter(Dict[int, SegmentedPage])


class FieldType(Enum):
    STRING = "string"
    BINARY = "binary"
    IMAGE_LIST = "image_list"
    STRING_LIST = "string_list"


class SchemaGenerator:
    """Generates both HuggingFace Features and PyArrow schemas from a field definition."""

    @staticmethod
    def _get_features_type(field_type: FieldType):
        mapping = {
            FieldType.STRING: Value("string"),
            FieldType.BINARY: Value("binary"),
            FieldType.IMAGE_LIST: Sequence(Features_Image()),
            FieldType.STRING_LIST: Sequence(Value("string")),
        }
        return mapping[field_type]

    @staticmethod
    def _get_pyarrow_type(field_type: FieldType):
        import pyarrow as pa

        image_type = pa.struct([("bytes", pa.binary()), ("path", pa.string())])

        mapping = {
            FieldType.STRING: pa.string(),
            FieldType.BINARY: pa.binary(),
            FieldType.IMAGE_LIST: pa.list_(image_type),
            FieldType.STRING_LIST: pa.list_(pa.string()),
        }
        return mapping[field_type]

    @classmethod
    def generate_features(cls, field_definitions: Dict[str, FieldType]) -> Features:
        return Features(
            {
                field_name: cls._get_features_type(field_type)
                for field_name, field_type in field_definitions.items()
            }
        )

    @classmethod
    def generate_pyarrow_schema(cls, field_definitions: Dict[str, FieldType]):
        import pyarrow as pa

        return pa.schema(
            [
                (field_name, cls._get_pyarrow_type(field_type))
                for field_name, field_type in field_definitions.items()
            ]
        )


class DatasetRecord(
    BaseModel
):  # TODO make predictionrecord class, factor prediction-related fields there.
    doc_id: str = Field(alias="document_id")
    doc_path: Optional[Path] = Field(alias="document_filepath", default=None)
    doc_hash: Optional[str] = Field(alias="document_filehash", default=None)

    ground_truth_doc: DoclingDocument = Field(alias="GroundTruthDocument")
    ground_truth_segmented_pages: Dict[int, SegmentedPage] = Field(
        alias="ground_truth_segmented_pages", default={}
    )
    original: Optional[Union[DocumentStream, Path]] = Field(
        alias="BinaryDocument", default=None
    )
    # TODO add optional columns to store the SegmentedPage, both for GT and prediction

    ground_truth_page_images: List[PIL.Image.Image] = Field(
        alias="GroundTruthPageImages", default=[]
    )
    ground_truth_pictures: List[PIL.Image.Image] = Field(
        alias="GroundTruthPictures", default=[]
    )

    mime_type: str = Field(default="application/pdf")
    modalities: List[EvaluationModality] = Field(default=[])
    tags: List[str] = Field(alias="tags", default_factory=list)

    model_config = ConfigDict(arbitrary_types_allowed=True, populate_by_name=True)

    @classmethod
    def get_field_alias(cls, field_name: str) -> str:
        return cls.model_fields[field_name].alias or field_name

    @classmethod
    def _get_field_definitions(cls) -> Dict[str, FieldType]:
        """Define the schema for this class. Override in subclasses to extend."""
        return {
            cls.get_field_alias("doc_id"): FieldType.STRING,
            cls.get_field_alias("doc_path"): FieldType.STRING,
            cls.get_field_alias("doc_hash"): FieldType.STRING,
            cls.get_field_alias("ground_truth_doc"): FieldType.STRING,
            cls.get_field_alias("ground_truth_segmented_pages"): FieldType.STRING,
            cls.get_field_alias("ground_truth_pictures"): FieldType.IMAGE_LIST,
            cls.get_field_alias("ground_truth_page_images"): FieldType.IMAGE_LIST,
            cls.get_field_alias("original"): FieldType.BINARY,
            cls.get_field_alias("mime_type"): FieldType.STRING,
            cls.get_field_alias("modalities"): FieldType.STRING_LIST,
            cls.get_field_alias("tags"): FieldType.STRING_LIST,
        }

    @classmethod
    def features(cls):
        return SchemaGenerator.generate_features(cls._get_field_definitions())

    @classmethod
    def pyarrow_schema(cls):
        """Generate PyArrow schema that matches the HuggingFace datasets image format."""
        return SchemaGenerator.generate_pyarrow_schema(cls._get_field_definitions())

    def _extract_images(
        self,
        document: DoclingDocument,
        pictures_field_prefix: str,
        pages_field_prefix: str,
    ):
        """
        Extract images using the global utility implementation.
        """
        _, pictures, page_images = extract_images(
            document=document,
            pictures_column=pictures_field_prefix,
            page_images_column=pages_field_prefix,
        )
        return pictures, page_images

    def as_record_dict(self):
        # Convert images to bytes format BEFORE closing them
        gt_pictures_bytes = self._images_to_bytes(self.ground_truth_pictures)
        gt_page_images_bytes = self._images_to_bytes(self.ground_truth_page_images)

        record = {
            self.get_field_alias("doc_id"): self.doc_id,
            self.get_field_alias("doc_path"): str(self.doc_path),
            self.get_field_alias("doc_hash"): self.doc_hash,
            self.get_field_alias("ground_truth_doc"): json.dumps(
                self.ground_truth_doc.export_to_dict()
            ),
            self.get_field_alias("ground_truth_pictures"): gt_pictures_bytes,
            self.get_field_alias("ground_truth_segmented_pages"): seg_adapter.dump_json(
                self.ground_truth_segmented_pages
            ).decode("utf-8"),
            self.get_field_alias("ground_truth_page_images"): gt_page_images_bytes,
            self.get_field_alias("mime_type"): self.mime_type,
            self.get_field_alias("modalities"): list(
                [m.value for m in self.modalities]
            ),
            self.get_field_alias("tags"): self.tags,
        }
        if isinstance(self.original, Path):
            with self.original.open("rb") as f:
                record.update({self.get_field_alias("original"): f.read()})
        elif isinstance(self.original, DocumentStream):
            record.update(
                {self.get_field_alias("original"): self.original.stream.read()}
            )
        else:
            record.update({self.get_field_alias("original"): None})

        return record

    @staticmethod
    def _pil_to_bytes(img: PIL.Image.Image) -> bytes:
        """Convert PIL image to PNG bytes."""
        buffered = BytesIO()
        img.save(buffered, format="PNG")
        return buffered.getvalue()

    def _images_to_bytes(self, images: List[PIL.Image.Image]) -> List[dict]:
        """Convert list of PIL Images to HuggingFace-compatible bytes format."""
        return [{"bytes": self._pil_to_bytes(img), "path": None} for img in images]

    @staticmethod
    def _close_image_list(images: List[PIL.Image.Image]) -> None:
        """Close all PIL Images in a list, logging any errors at debug level."""
        for img in images:
            try:
                img.close()
            except Exception as e:
                _log.debug(f"Failed to close PIL image: {e}")

    def _close_images(self) -> None:
        """Close ground truth PIL Images to prevent memory leaks."""
        self._close_image_list(self.ground_truth_page_images)
        self._close_image_list(self.ground_truth_pictures)
        self.ground_truth_page_images = []
        self.ground_truth_pictures = []

    @model_validator(mode="after")
    def validate_images(self) -> "DatasetRecord":
        if not len(self.ground_truth_pictures) and not len(
            self.ground_truth_page_images
        ):
            pictures, page_images = self._extract_images(
                self.ground_truth_doc,
                pictures_field_prefix=self.get_field_alias("ground_truth_pictures"),
                pages_field_prefix=self.get_field_alias("ground_truth_page_images"),
            )

            self.ground_truth_page_images = page_images
            self.ground_truth_pictures = pictures

        return self

    @model_validator(mode="before")
    @classmethod
    def validate_record_dict(cls, data: dict):
        gt_doc_alias = cls.get_field_alias("ground_truth_doc")
        if gt_doc_alias in data and isinstance(data[gt_doc_alias], str):
            data[gt_doc_alias] = json.loads(data[gt_doc_alias])

        gt_seg_pages_alias = cls.get_field_alias("ground_truth_segmented_pages")
        if gt_seg_pages_alias in data and isinstance(
            data[gt_seg_pages_alias], (str, bytes)
        ):
            seg_pages_data = data[gt_seg_pages_alias]
            if isinstance(seg_pages_data, bytes):
                seg_pages_data = seg_pages_data.decode("utf-8")
            data[gt_seg_pages_alias] = seg_adapter.validate_json(seg_pages_data)

        gt_page_img_alias = cls.get_field_alias("ground_truth_page_images")
        if gt_page_img_alias in data:
            for ix, item in enumerate(data[gt_page_img_alias]):
                if isinstance(item, dict):
                    data[gt_page_img_alias][ix] = Features_Image().decode_example(item)

        gt_pic_img_alias = cls.get_field_alias("ground_truth_pictures")
        if gt_pic_img_alias in data:
            for ix, item in enumerate(data[gt_pic_img_alias]):
                if isinstance(item, dict):
                    data[gt_pic_img_alias][ix] = Features_Image().decode_example(item)

        gt_binary = cls.get_field_alias("original")
        if gt_binary in data:
            if isinstance(data[gt_binary], bytes):
                data[gt_binary] = DocumentStream(
                    name="file", stream=BytesIO(data[gt_binary])
                )
            elif isinstance(data[gt_binary], PIL.Image.Image):
                # Handle PIL Images by converting to bytes
                img_buffer = BytesIO()
                data[gt_binary].save(img_buffer, format="PNG")
                img_buffer.seek(0)
                data[gt_binary] = DocumentStream(name="image.png", stream=img_buffer)

        # Backward compatibility: ensure tags field exists for old datasets and is not None
        tags_alias = cls.get_field_alias("tags")
        if tags_alias not in data or data[tags_alias] is None:
            data[tags_alias] = []

        return data


class DatasetRecordWithBBox(DatasetRecord):
    """Add extra column (named GroundTruthBboxOnPageImages) to DatasetRecord that contains

     GroundTruthBboxOnPageImages: JSON dict: page_number (zero based) to a list of box objects, each with:
        - label: string class name (e.g. "table")
        - category_id: integer category ID
        - bbox: [x, y, width, height] in COCO format
        - ltrb: [left, top, right, bottom]

    Note: the page_number is the index in the array of the GroundTruthPageImages.
    """

    ground_truth_bbox_on_page_images: Dict[int, List[Dict]] = Field(
        alias="GroundTruthBboxOnPageImages", default_factory=dict
    )

    @classmethod
    def _get_field_definitions(cls) -> Dict[str, FieldType]:
        base_definitions = super()._get_field_definitions()
        return {
            **base_definitions,
            cls.get_field_alias("ground_truth_bbox_on_page_images"): FieldType.STRING,
        }

    def as_record_dict(self):
        record = super().as_record_dict()
        record.update(
            {
                self.get_field_alias("ground_truth_bbox_on_page_images"): json.dumps(
                    self.ground_truth_bbox_on_page_images
                )
            }
        )
        return record

    def get_page_images_with_bboxes(self) -> List[Tuple[PIL.Image.Image, List[Dict]]]:
        """Pair each ground-truth page image with its zero-based page bbox payload."""
        return [
            (page_image, self.ground_truth_bbox_on_page_images.get(page_index, []))
            for page_index, page_image in enumerate(self.ground_truth_page_images)
        ]

    @staticmethod
    def _validate_coco_bbox(
        bbox: List[Union[int, float]],
        page_width: int,
        page_height: int,
        page_index: int,
        box_index: int,
    ) -> None:
        if len(bbox) != 4:
            raise ValueError(
                f"Page {page_index} bbox #{box_index} has invalid COCO bbox length; expected 4 values."
            )
        x, y, width, height = bbox
        if x < 0 or y < 0 or width < 0 or height < 0:
            raise ValueError(
                f"Page {page_index} bbox #{box_index} must be non-negative."
            )
        if x + width > page_width or y + height > page_height:
            raise ValueError(
                f"Page {page_index} bbox #{box_index} exceeds page image bounds "
                f"{page_width}x{page_height}."
            )

    @staticmethod
    def _validate_ltrb_bbox(
        ltrb: List[Union[int, float]],
        page_width: int,
        page_height: int,
        page_index: int,
        box_index: int,
    ) -> None:
        if len(ltrb) != 4:
            raise ValueError(
                f"Page {page_index} bbox #{box_index} has invalid ltrb length; expected 4 values."
            )
        left, top, right, bottom = ltrb
        if left < 0 or top < 0 or right < left or bottom < top:
            raise ValueError(
                f"Page {page_index} bbox #{box_index} has invalid ltrb coordinates."
            )
        if right > page_width or bottom > page_height:
            raise ValueError(
                f"Page {page_index} bbox #{box_index} exceeds page image bounds "
                f"{page_width}x{page_height}."
            )

    @model_validator(mode="before")
    @classmethod
    def validate_bbox_record_dict(cls, data: dict):
        bbox_alias = cls.get_field_alias("ground_truth_bbox_on_page_images")
        if bbox_alias in data and isinstance(data[bbox_alias], str):
            data[bbox_alias] = json.loads(data[bbox_alias])

        if bbox_alias not in data or data[bbox_alias] is None:
            data[bbox_alias] = {}
        else:
            data[bbox_alias] = {int(k): v for k, v in data[bbox_alias].items()}

        return data

    @model_validator(mode="after")
    def validate_bboxes(self) -> "DatasetRecordWithBBox":
        for page_index, boxes in self.ground_truth_bbox_on_page_images.items():
            if page_index < 0 or page_index >= len(self.ground_truth_page_images):
                raise ValueError(
                    f"Bounding boxes reference missing page image index {page_index}."
                )

            page_image = self.ground_truth_page_images[page_index]
            page_width, page_height = page_image.size

            for box_index, box in enumerate(boxes):
                coord_origin = box.get("coord_origin", CoordOrigin.TOPLEFT.value)
                if coord_origin != CoordOrigin.TOPLEFT.value:
                    raise ValueError(
                        f"Page {page_index} bbox #{box_index} must use TOPLEFT coordinates."
                    )

                if "bbox" in box and box["bbox"] is not None:
                    self._validate_coco_bbox(
                        box["bbox"], page_width, page_height, page_index, box_index
                    )

                if "ltrb" in box and box["ltrb"] is not None:
                    self._validate_ltrb_bbox(
                        box["ltrb"], page_width, page_height, page_index, box_index
                    )

        return self


class DatasetRecordWithPrediction(DatasetRecord):
    predictor_info: Dict = Field(alias="predictor_info", default={})
    status: ConversionStatus = Field(alias="status", default=ConversionStatus.PENDING)

    predicted_doc: Optional[DoclingDocument] = Field(
        alias="PredictedDocument", default=None
    )

    predicted_segmented_pages: Dict[int, SegmentedPage] = Field(
        alias="predicted_segmented_pages", default={}
    )

    original_prediction: Optional[str] = None
    prediction_format: PredictionFormats = (
        PredictionFormats.DOCLING_DOCUMENT
    )  # default for old files
    prediction_timings: Optional[Dict] = Field(alias="prediction_timings", default=None)

    predicted_page_images: List[PIL.Image.Image] = Field(
        alias="PredictionPageImages", default=[]
    )
    predicted_pictures: List[PIL.Image.Image] = Field(
        alias="PredictionPictures", default=[]
    )

    model_config = ConfigDict(arbitrary_types_allowed=True, populate_by_name=True)

    @classmethod
    def _get_field_definitions(cls) -> Dict[str, FieldType]:
        """Extend the parent schema with prediction-specific fields."""
        base_definitions = super()._get_field_definitions()
        prediction_definitions = {
            cls.get_field_alias("predictor_info"): FieldType.STRING,
            cls.get_field_alias("status"): FieldType.STRING,
            cls.get_field_alias("predicted_doc"): FieldType.STRING,
            cls.get_field_alias("predicted_segmented_pages"): FieldType.STRING,
            cls.get_field_alias("predicted_pictures"): FieldType.IMAGE_LIST,
            cls.get_field_alias("predicted_page_images"): FieldType.IMAGE_LIST,
            cls.get_field_alias("prediction_format"): FieldType.STRING,
            cls.get_field_alias("prediction_timings"): FieldType.STRING,
            cls.get_field_alias("original_prediction"): FieldType.STRING,
        }
        return {**base_definitions, **prediction_definitions}

    @classmethod
    def features(cls):
        return SchemaGenerator.generate_features(cls._get_field_definitions())

    @classmethod
    def pyarrow_schema(cls):
        """Generate PyArrow schema that matches the HuggingFace datasets image format."""
        return SchemaGenerator.generate_pyarrow_schema(cls._get_field_definitions())

    def as_record_dict(self):
        record = super().as_record_dict()
        record.update(
            {
                self.get_field_alias("prediction_format"): self.prediction_format.value,
                self.get_field_alias("prediction_timings"): (
                    json.dumps(self.prediction_timings)
                    if self.prediction_timings is not None
                    else None
                ),
                self.get_field_alias("predictor_info"): json.dumps(self.predictor_info),
                self.get_field_alias("status"): self.status.value,
            }
        )

        if self.predicted_doc is not None:
            # Convert prediction images to bytes BEFORE closing
            pred_pictures_bytes = self._images_to_bytes(self.predicted_pictures)
            pred_page_images_bytes = self._images_to_bytes(self.predicted_page_images)

            record.update(
                {
                    self.get_field_alias("predicted_doc"): json.dumps(
                        self.predicted_doc.export_to_dict()
                    ),
                    self.get_field_alias(
                        "predicted_segmented_pages"
                    ): seg_adapter.dump_json(self.predicted_segmented_pages).decode(
                        "utf-8"
                    ),
                    self.get_field_alias("predicted_pictures"): pred_pictures_bytes,
                    self.get_field_alias(
                        "predicted_page_images"
                    ): pred_page_images_bytes,
                    self.get_field_alias("original_prediction"): (
                        self.original_prediction
                    ),
                }
            )

        # Close prediction images (parent already closed ground truth images)
        self._close_prediction_images()
        return record

    def _close_prediction_images(self) -> None:
        """Close prediction PIL Images to prevent memory leaks."""
        self._close_image_list(self.predicted_page_images)
        self._close_image_list(self.predicted_pictures)
        self.predicted_page_images = []
        self.predicted_pictures = []

    @model_validator(mode="after")
    def validate_images(self) -> "DatasetRecordWithPrediction":
        # super().validate_images()

        if self.predicted_doc is not None:
            if not len(self.predicted_pictures) and not len(self.predicted_page_images):
                pictures, page_images = self._extract_images(
                    self.predicted_doc,
                    pictures_field_prefix=self.get_field_alias("predicted_pictures"),
                    pages_field_prefix=self.get_field_alias("predicted_page_images"),
                )

                self.predicted_page_images = page_images
                self.predicted_pictures = pictures

        return self

    @model_validator(mode="before")
    @classmethod
    def validate_prediction_record_dict(cls, data: dict):
        info_alias = cls.get_field_alias("predictor_info")
        if info_alias in data and isinstance(data[info_alias], str):
            data[info_alias] = json.loads(data[info_alias])

        timings_alias = cls.get_field_alias("prediction_timings")
        if timings_alias in data and isinstance(data[timings_alias], str):
            # try:
            data[timings_alias] = json.loads(data[timings_alias])
            # except json.JSONDecodeError:
            #    data[timings_alias] = None

        pred_doc_alias = cls.get_field_alias("predicted_doc")
        if pred_doc_alias in data and isinstance(data[pred_doc_alias], str):
            data[pred_doc_alias] = json.loads(data[pred_doc_alias])

        pred_seg_pages_alias = cls.get_field_alias("predicted_segmented_pages")
        if pred_seg_pages_alias in data and isinstance(
            data[pred_seg_pages_alias], (str, bytes)
        ):
            seg_pages_data = data[pred_seg_pages_alias]
            if isinstance(seg_pages_data, bytes):
                seg_pages_data = seg_pages_data.decode("utf-8")
            data[pred_seg_pages_alias] = seg_adapter.validate_json(seg_pages_data)

        pred_page_img_alias = cls.get_field_alias("predicted_page_images")
        if pred_page_img_alias in data:
            for ix, item in enumerate(data[pred_page_img_alias]):
                if isinstance(item, dict):
                    data[pred_page_img_alias][ix] = Features_Image().decode_example(
                        item
                    )

        pred_pic_img_alias = cls.get_field_alias("predicted_pictures")
        if pred_pic_img_alias in data:
            for ix, item in enumerate(data[pred_pic_img_alias]):
                if isinstance(item, dict):
                    data[pred_pic_img_alias][ix] = Features_Image().decode_example(item)

        return data

